import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import { EventsIndexView } from '@/components/events/EventListViews';
import { getUpcomingStopSummaries, type EventStopSummary } from '@/lib/events/event-stops';
import { EVENT_SHOWS, EVENTS_INDEX_PATH, EVENTS_SITE_URL, isEventsPagesLive, type EventShow } from '@/lib/events/event-pages';

// /events (Phase 2, 2026-11-18): the shows that have pages and the next
// upcoming stops by date. EVENTS_PAGES_LIVE unset or not "true": a 404 before
// any read. ISR, regenerated by the pipeline's revalidate, the nightly
// refresh, or after a day.
export const revalidate = 86400;

const NEXT_STOPS = 12;
const TITLE = 'Events at Stadiums and Arenas: Dates, Tickets and Venue Guides';
const DESCRIPTION = 'Touring shows at the stadiums and arenas PromoNight covers, with showtimes, a ticket link for every show, and each venue\'s bag, parking and transit details.';

async function load(now: Date) {
  const shows: Array<{ show: EventShow; stops: number; performances: number; first: string | null; last: string | null }> = [];
  const all: EventStopSummary[] = [];
  for (const show of Object.values(EVENT_SHOWS)) {
    const stops = await getUpcomingStopSummaries(show.slug, now);
    all.push(...stops);
    shows.push({ show, stops: stops.length, performances: stops.reduce((n, s) => n + s.upcomingCount, 0), first: stops[0]?.nextDate ?? null, last: stops.map((s) => s.lastDate).sort().pop() ?? null });
  }
  return { shows, next: all.sort((a, b) => a.nextDate.localeCompare(b.nextDate) || a.venueSlug.localeCompare(b.venueSlug)).slice(0, NEXT_STOPS) };
}

export async function generateMetadata(): Promise<Metadata> {
  if (!isEventsPagesLive()) return {};
  const canonical = `${EVENTS_SITE_URL}${EVENTS_INDEX_PATH}`;
  return {
    title: TITLE,
    description: DESCRIPTION,
    alternates: { canonical },
    openGraph: { type: 'website', siteName: 'PromoNight', url: canonical, title: `${TITLE} | PromoNight`, description: DESCRIPTION },
  };
}

export default async function EventsIndexPage() {
  if (!isEventsPagesLive()) notFound();
  const { shows, next } = await load(new Date());
  return <EventsIndexView shows={shows} next={next} />;
}
